(function(root){
'use strict';
const departments=[['concierge','Консьерж','Concierge'],['restaurant','Ресторан','Restaurant'],['bar','Бар','Bar'],['market','Мини-маркет','Mini market'],['cleaning','Клининг','Cleaning'],['laundry','Прачечная','Laundry'],['electrician','Электрик','Electrician'],['plumber','Сантехник','Plumber'],['carpenter','Плотник','Carpenter'],['travel','Туры и гиды','Tours & guides'],['tickets','Авиа / ЖД / автобусы','Flight / rail / bus desk'],['mobility','Такси / аренда авто','Taxi / car rental'],['property','Недвижимость','Real estate']];
const options=[['transfer','Трансфер','Transfer',180000,'group','mobility'],['rail','ЖД билет','Rail ticket',350000,'person','tickets'],['bus','Автобус','Bus',120000,'person','tickets'],['meals','Питание 3 раза в день','3 meals daily',350000,'person-day','restaurant'],['guide','Личный гид','Private guide',900000,'group','travel'],['museum','Музеи','Museums',80000,'person','travel'],['mountains','Амирсой / Чимган / Чарвак','Amirsoy / Chimgan / Charvak',750000,'person','travel']];
function quote({guests,days,selected,stayPrice=null,nights=0}){if(!Number.isInteger(guests)||guests<1||guests>20||!Number.isInteger(days)||days<1||days>30||!Array.isArray(selected)||selected.some(id=>!options.some(o=>o[0]===id)))throw Error('Invalid package');const lines=options.filter(o=>selected.includes(o[0])).map(o=>({id:o[0],department:o[5],amount:o[3]*(o[4]==='person'?guests:o[4]==='person-day'?guests*days:1)}));if(nights){if(!Number.isInteger(nights)||nights<1||nights>30||!(stayPrice===null||Number.isFinite(stayPrice)&&stayPrice>0))throw Error('Invalid stay');lines.unshift({id:'stay',department:'concierge',amount:stayPrice===null?null:stayPrice*nights});}return {lines,total:lines.some(l=>l.amount===null)?null:lines.reduce((s,l)=>s+l.amount,0)};}
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validTask=t=>t&&typeof t.id==='string'&&typeof t.ru==='string'&&typeof t.en==='string'&&departments.some(d=>d[0]===t.department)&&['new','progress','done','cancelled'].includes(t.status)&&typeof t.note==='string'&&t.note.length<=1200;
if(typeof module!=='undefined')module.exports={quote,escape,validTask,options};
if(!root.document)return;
const key='vertex-unified-v1',tx=(ru,en)=>lang==='en'?en:ru,fmt=n=>n===null?tx('Нужен расчёт','Quote required'):money(n,'UZS');
let state={tasks:[],packages:[]},role='guest',department='all',storageError=false;
try{const s=JSON.parse(localStorage.getItem(key)||'null');if(s){state.tasks=Array.isArray(s.tasks)?s.tasks.filter(validTask).slice(0,200):[];state.packages=Array.isArray(s.packages)?s.packages.filter(p=>p&&typeof p.id==='string'&&typeof p.city==='string'&&Number.isInteger(p.guests)&&p.guests>=1&&p.guests<=20&&/^\d{4}-\d{2}-\d{2}$/.test(p.start)&&/^\d{4}-\d{2}-\d{2}$/.test(p.end)&&Array.isArray(p.lines)&&p.lines.every(l=>l&&typeof l.id==='string'&&(l.amount===null||Number.isFinite(l.amount)&&l.amount>=0))&&(p.total===null||Number.isFinite(p.total)&&p.total>=0)).slice(0,50):[];}}catch{storageError=true;}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageError=false;}catch{storageError=true;}}
const uid=()=>crypto.randomUUID();
const cityLabel=id=>{const c=window.VertexCatalog?.cities?.find(c=>c.id===id);return c?tx(c.ru,c.en):id;};
const depName=id=>{const d=departments.find(d=>d[0]===id);return d?tx(d[1],d[2]):id;};
const notice=()=>`<p class="notice">${tx('Демо на одном устройстве: переключение ролей не является входом. Заявки не отправляются реальным сотрудникам.','Single-device demo: role switching is not sign-in. Requests are not sent to real employees.')}</p>${storageError?`<p role="alert">${tx('Сохранение недоступно. Данные могут исчезнуть после закрытия.','Storage unavailable. Data may be lost after closing.')}</p>`:''}`;
function request(serviceId){const s=services.find(s=>s.id===serviceId);const routes={taxi:'mobility',comfort:'mobility',car:'mobility',flight:'tickets',rail:'tickets',bus:'tickets',market:'market',meal:'restaurant',meals3:'restaurant',bar:'bar',laundry:'laundry',concierge:'concierge',cleaning:'cleaning',electrician:'electrician',plumber:'plumber',carpenter:'carpenter',tour:'travel',guide:'travel',museum:'travel',resort:'travel',propertyRent:'property',propertyBuy:'property',propertySell:'property'};const dep=routes[serviceId]||'concierge';modal(tx('Заявка','Service request'),`${notice()}<h3>${escape(s?tx(s.ru,s.en):depName(dep))}</h3><p>${tx('Отдел','Department')}: ${escape(depName(dep))}</p><form id="groupRequestForm"><label>${tx('Пожелания гостя','Guest request')}<textarea id="groupNote" maxlength="1200" required rows="3"></textarea></label><button class="dark wide">${tx('Создать демо-заявку','Create demo request')}</button></form>`);$('groupRequestForm').onsubmit=e=>{e.preventDefault();const note=$('groupNote').value.trim();if(!note)return;state.tasks.unshift({id:uid(),ru:s?.ru||'Консьерж',en:s?.en||'Concierge',department:dep,note,status:'new',assignee:'',created:new Date().toISOString()});state.tasks=state.tasks.slice(0,200);save();tasks();};}
function tasks(){const status={new:tx('Новая','New'),progress:tx('В работе','In progress'),done:tx('Выполнено','Done'),cancelled:tx('Отменено','Cancelled')};const visible=state.tasks.filter(t=>role==='guest'||department==='all'||t.department===department);modal(tx('Заявки и команда','Requests & team'),`${notice()}<div class="group-controls"><label>${tx('Демо-роль','Demo role')}<select id="groupRole">${[['guest','Гость','Guest'],['staff','Персонал','Staff'],['admin','Администратор','Admin']].map(o=>`<option value="${o[0]}" ${role===o[0]?'selected':''}>${tx(o[1],o[2])}</option>`).join('')}</select></label>${role!=='guest'?`<label>${tx('Отдел','Department')}<select id="groupDepartment"><option value="all">${tx('Все отделы','All departments')}</option>${departments.map(d=>`<option value="${d[0]}" ${department===d[0]?'selected':''}>${tx(d[1],d[2])}</option>`).join('')}</select></label>`:''}</div><div class="group-list">${visible.map(t=>`<article class="group-card"><b>${escape(tx(t.ru,t.en))}</b><p>${escape(depName(t.department))} · ${escape(status[t.status])}</p><p class="group-note">${escape(t.note)}</p>${t.assignee?`<small>${tx('Исполнитель','Assignee')}: ${escape(t.assignee)}</small>`:''}<div class="group-controls">${role==='admin'&&!['done','cancelled'].includes(t.status)?`<button data-assign="${escape(t.id)}">${tx('Назначить','Assign')}</button>`:''}${role!=='guest'&&t.status==='new'?`<button data-status="progress" data-task="${escape(t.id)}">${tx('В работу','Start')}</button>`:''}${role!=='guest'&&t.status==='progress'?`<button data-status="done" data-task="${escape(t.id)}">${tx('Завершить','Complete')}</button>`:''}${t.status==='new'?`<button data-status="cancelled" data-task="${escape(t.id)}">${tx('Отменить','Cancel')}</button>`:''}</div></article>`).join('')||`<p>${tx('Заявок пока нет.','No requests yet.')}</p>`}</div><button id="groupNew" class="dark wide">${tx('Создать заявку','Create request')}</button>`);$('groupRole').onchange=e=>{role=e.target.value;tasks();};if($('groupDepartment'))$('groupDepartment').onchange=e=>{department=e.target.value;tasks();};$('groupNew').onclick=()=>request('concierge');$('modalBody').querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.task);if(t){t.status=b.dataset.status;save();tasks();}});$('modalBody').querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.assign);modal(tx('Исполнитель','Assignee'),`<form id="groupAssign"><label>${tx('Имя сотрудника (демо)','Employee name (demo)')}<input id="groupEmployee" maxlength="80" required></label><button class="dark wide">${tx('Сохранить','Save')}</button></form>`);$('groupAssign').onsubmit=e=>{e.preventDefault();t.assignee=$('groupEmployee').value.trim();save();tasks();};});}
function packages(){modal(tx('Турпакеты поездки','Travel packages'),`${notice()}${state.packages.map(p=>`<article class="group-card"><b>${escape(cityLabel(p.city))}</b><p>${escape(p.start)} → ${escape(p.end)} · ${p.guests} ${tx('гостей','guests')}</p>${p.lines.map(l=>`<div class="line-item"><span>${escape(l.id==='stay'?tx('Проживание','Accommodation'):tx(...(options.find(o=>o[0]===l.id)||['','Услуга','Service']).slice(1,3)))}</span><strong>${fmt(l.amount)}</strong></div>`).join('')}<p>${tx('Итого','Total')}: <strong>${fmt(p.total)}</strong> · ${tx('Демо, не оплачено','Demo, unpaid')}</p><button data-cancel-package="${escape(p.id)}">${tx('Удалить пакет','Remove package')}</button></article>`).join('')||`<p>${tx('Пакетов пока нет.','No packages yet.')}</p>`}<button id="groupBuild" class="dark wide">${tx('Собрать турпакет','Build a package')}</button>`);$('groupBuild').onclick=builder;$('modalBody').querySelectorAll('[data-cancel-package]').forEach(b=>b.onclick=()=>{state.packages=state.packages.filter(p=>p.id!==b.dataset.cancelPackage);state.tasks.forEach(t=>{if(t.packageId===b.dataset.cancelPackage&&!['done','cancelled'].includes(t.status))t.status='cancelled';});save();packages();});}
function builder(){const cities=window.VertexCatalog?.cities||[{id:'Tashkent',ru:'Ташкент',en:'Tashkent'},{id:'Samarkand',ru:'Самарканд',en:'Samarkand'},{id:'Bukhara',ru:'Бухара',en:'Bukhara'},{id:'Khiva',ru:'Хива',en:'Khiva'}];modal(tx('Конструктор путешествия','Travel builder'),`<p class="notice">${tx('Условные тарифы в UZS для демонстрации расчёта. Реальные цены, наличие и оплату подтвердит команда.','Illustrative UZS rates for demonstration. The team must confirm actual prices, availability and payment.')}</p><form id="groupPackageForm"><div class="group-controls"><label>${tx('Город','City')}<select id="groupCity">${cities.map(c=>`<option value="${escape(c.id)}">${escape(tx(c.ru,c.en))}</option>`).join('')}</select></label><label>${tx('Гостей','Guests')}<input id="groupGuests" type="number" min="1" max="20" value="2" required></label><label>${tx('Заезд','Check-in')}<input type="date" id="groupStart" value="${$('arrival').value}" required></label><label>${tx('Выезд','Check-out')}<input type="date" id="groupEnd" value="${$('departure').value}" required></label></div><label>${tx('Проживание','Accommodation')}<select id="groupStay"></select></label><div class="group-options">${options.map(o=>`<label><input type="checkbox" name="groupOption" value="${o[0]}"><span>${tx(o[1],o[2])}<small>${fmt(o[3])} / ${o[4]==='group'?tx('группа','group'):o[4]==='person'?tx('человек','person'):tx('человек в день','person/day')}</small></span></label>`).join('')}</div><p id="groupQuote" role="status"></p><button class="dark wide">${tx('Сохранить пакет и задачи','Save package & tasks')}</button></form>`);function fill(){const list=stays.filter(s=>s.city===$('groupCity').value);$('groupStay').innerHTML=`<option value="">${tx('Без проживания','No accommodation')}</option>`+list.map(s=>`<option value="${escape(s.id)}">${escape(tx(s.ru,s.en))} · ${fmt(s.price)}</option>`).join('');}
function calc(){const start=$('groupStart').value,end=$('groupEnd').value,days=Math.round((Date.parse(end)-Date.parse(start))/86400000),guests=Number($('groupGuests').value);const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(!Number.isFinite(days)||Date.parse(start)<today.getTime())throw Error(tx('Проверьте даты: заезд сегодня или позже.','Check dates: arrival must be today or later.'));const s=stays.find(s=>s.id===$('groupStay').value);if(s&&guests>s.capacity)throw Error(tx('Превышена вместимость жилья.','Accommodation capacity exceeded.'));const q=quote({guests,days,selected:[...document.querySelectorAll('[name="groupOption"]:checked')].map(x=>x.value),stayPrice:s?.price??null,nights:s?days:0});if(!q.lines.length)throw Error(tx('Выберите жильё или услуги.','Select accommodation or services.'));return {...q,start,end,guests,city:$('groupCity').value,stayId:s?.id||null};}
function preview(){try{const q=calc();$('groupQuote').textContent=tx('Итого: ','Total: ')+fmt(q.total);}catch(e){$('groupQuote').textContent=e.message==='Invalid package'?tx('Выберите от 1 до 30 ночей и от 1 до 20 гостей.','Choose 1–30 nights and 1–20 guests.'):e.message;}}
fill();$('groupCity').onchange=()=>{fill();preview();};$('groupPackageForm').oninput=preview;preview();$('groupPackageForm').onsubmit=e=>{e.preventDefault();let q;try{q=calc();}catch{preview();return;}const id=uid();state.packages.unshift({...q,id});state.packages=state.packages.slice(0,50);q.lines.forEach(l=>{const o=options.find(o=>o[0]===l.id);state.tasks.unshift({id:uid(),packageId:id,ru:o?.[1]||'Проживание',en:o?.[2]||'Accommodation',department:l.department,note:`${q.city} · ${q.start} → ${q.end} · ${q.guests}`,status:'new',assignee:'',created:new Date().toISOString()});});state.tasks=state.tasks.slice(0,200);save();packages();};}
const extras=[['bus','tickets','Автобусные билеты','Bus tickets'],['meals3','food','Питание 3 раза в день','3 meals daily'],['cleaning','care','Клининг','Cleaning'],['electrician','care','Электрик','Electrician'],['plumber','care','Сантехник','Plumber'],['carpenter','care','Плотник','Carpenter'],['museum','explore','Музеи','Museums'],['resort','explore','Горный отдых','Mountain escapes'],['propertyRent','property','Арендовать недвижимость','Rent property'],['propertyBuy','property','Купить недвижимость','Buy property'],['propertySell','property','Продать недвижимость','Sell property']];
extras.forEach(([id,cat,ru,en])=>{if(!services.some(s=>s.id===id))services.push({id,cat,ru,en,icon:'✧',price:null,currency:'UZS',descRu:'Демо-заявка в профильный отдел · цену уточнит команда',descEn:'Demo request to the relevant team · price on request'});});if(!cats.some(c=>c[0]==='property'))cats.push(['property','⌂','Недвижимость','Real estate']);
const oldAdd=addService;addService=function(id){if(services.some(s=>s.id===id))return request(id);return oldAdd(id);};
const entry=document.createElement('section');entry.className='group-entry';document.querySelector('footer').before(entry);
function refresh(){entry.innerHTML=`<div><span class="eyebrow">VERTEX GROUP</span><h2>${tx('Гость и команда — вместе','Guest and team, connected')}</h2><p>${tx('Турпакеты, заявки и исполнение услуг в одной демо-версии.','Packages, requests and service delivery in one demo.')}</p></div><div class="group-controls"><button id="groupOpenPackages" class="dark">${tx('Турпакеты','Packages')}</button><button id="groupOpenTasks" class="outline">${tx('Заявки и команда','Requests & team')}</button></div>`;$('groupOpenPackages').onclick=packages;$('groupOpenTasks').onclick=tasks;}
const priorRender=render;render=function(){priorRender();refresh();};
// Keep the existing trips overview and append the same persistent package ledger.
const tripObserver=new MutationObserver(()=>{if(!$('modal').open||$('groupTripLink'))return;const title=$('modalTitle').textContent;if(!/^(Поездки|Trips|Ваша поездка|Your trip)$/i.test(title))return;const button=document.createElement('button');button.id='groupTripLink';button.className='outline wide';button.textContent=tx('Турпакеты и задачи поездки','Trip packages & tasks');button.onclick=packages;$('modalBody').append(button);});tripObserver.observe($('modalBody'),{childList:true});
window.VertexGroup={requests:tasks,packages,builder,request};render();
})(typeof window==='undefined'?globalThis:window);
